window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[361]={"id":"361","numero":361,"titre":"Lésions périarticulaires et ligamentaires","objectifs":[{"id":"361-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une tendinopathie, d’une bursopathie, d’une enthésopathie","contenu":"<div class=\"obj-callout success\"><strong>Trois entités péri-articulaires à distinguer.</strong> Toutes touchent <span class=\"kw-clinique\">les</span> structures <span class=\"kw-def\">autour de l’articulation</span> (tendons, bourses, enthèses) et non l’articulation elle-même.</div>\n\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Tendinopathie</span></strong></td>\n            <td>Pathologie <span class=\"kw-etio\">inflammatoire et/ou dégénérative</span> des <span class=\"kw-def\">tendons</span> (structures fibreuses reliant muscle et os).<br>Le terme <span class=\"kw-def\">« tendinite »</span> est impropre : l’examen microscopique montre une <span class=\"kw-etio\">dégénérescence</span>, pas d’inflammation (sauf inflammation de la gaine).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Bursopathie</span></strong></td>\n            <td>Pathologie mécanique, <span class=\"kw-etio\">inflammatoire</span> (microcristalline, rhumatismale) ou <span class=\"kw-etio\">infectieuse</span> d’une <span class=\"kw-def\">bourse séreuse</span> (tissu de glissement entre peau, muscles, tendons, l<span class=\"kw-chiffre\">iga</span>ments et os).<br><span class=\"kw-def\">Hygroma</span> = bursopathie <strong>superficielle</strong> (coude, genou).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Enthésopathie</span></strong></td>\n            <td>Pathologie des <span class=\"kw-def\">enthèses</span>, c’est-à-dire des <strong>insertions tendino-capsulo-l<span class=\"kw-chiffre\">iga</span>mentaires sur l’os</strong>.<br><strong>Mécanique</strong> (sportif, gestes répétitifs) ou <strong><span class=\"kw-etio\">inflammatoire</span></strong> (<span class=\"kw-etio\">spondylarthropathies</span> : SPA, rhumatisme psoriasique, <span class=\"kw-clinique\">MICI</span>) → enthésite, pouvant aller jusqu’à l’<span class=\"kw-def\">enthésophyte</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Bourse séreuse — repère.</strong> Superficielle (sous la peau : olécrane, rotule) ou profonde (sous muscles/tendons : <span class=\"kw-def\">bourse sous-acromiale</span> de l’épaule). Remplie de liquide synovial, elle peut être le siège d’un épanchement satellite d’une souffrance tendineuse.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/tendinopathy-1","label":"Radiopaedia : tendinopathie"},{"href":"https://radiopaedia.org/articles/bursitis","label":"Radiopaedia : bursite"}]},{"id":"361-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisant des tendinopathies","contenu":"<div class=\"callout callout-info\"><strong>Tendon = structure adaptative.</strong> Dès <span class=\"kw-chiffre\">20 ans</span> il perd de l’eau puis ses fibres élastiques ; dès <span class=\"kw-chiffre\">35 ans</span> commence le « 3<sup>e</sup> âge du tendon ». <span class=\"kw-clinique\">Les</span> tendons de la <span class=\"kw-def\">coiffe des rotateurs</span> dégénèrent le plus tôt (très sollicités). L’immobilisation entraîne une <span class=\"kw-clinique\">atrophie tendineuse</span> ; la sur-sollicitation de tendons mal échauffés ou fragilisés crée des <span class=\"kw-clinique\">micro-ruptures</span>.</div>\n\n      <table >\n        <thead><tr><th>Famille de facteurs</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Extrinsèques (gestuelle)</strong></td>\n            <td><span class=\"kw-etio\">Défaut de progressivité</span> (changement de poste) ; outils trop lourds ; <span class=\"kw-etio\">poste de travail inadapté</span> ; gestes répétitifs à risque (taille de haies, sécateur, poste informatique, tennis)</td>\n          </tr>\n          <tr>\n            <td><strong>Locaux</strong></td>\n            <td><span class=\"kw-etio\">Conflit antérieur de l’épaule</span> (accrochage acromion / bourse / coiffe) par déséquilibre musculaire, <span class=\"kw-imagerie\">bec acromial</span>, arthrose acromio-claviculaire</td>\n          </tr>\n          <tr>\n            <td><strong>Troubles d’axe / torsion</strong></td>\n            <td><span class=\"kw-etio\">Genu valgum</span> → tendons de la <strong>patte d’oie</strong> ; <span class=\"kw-etio\">genu varum</span> → <strong>bandelette ilio-tibiale</strong> ; recurvatum du coude → épicondyliens ; raideur musculo-tendineuse</td>\n          </tr>\n          <tr>\n            <td><strong>Métaboliques</strong></td>\n            <td><span class=\"kw-etio\">Hyperuricémie</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-clinique\">déshydratation</span>, amylose</td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes</strong></td>\n            <td><span class=\"kw-ci\">Fluoroquinolones</span> (risque de <span class=\"kw-alerte\">rupture</span> totale, même en cure courte) ; <span class=\"kw-ci\">corticothérapie</span> ; vitamine A / <span class=\"kw-ttt\">isotrétinoïne</span> ; <span class=\"kw-ttt\">statines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Rhumatismales</strong></td>\n            <td><span class=\"kw-etio\">Spondylarthropathies</span>, rhumatisme psoriasique, <span class=\"kw-clinique\">PR</span> (ténosynovites), goutte, rhumatisme à apatite / pyrophosphate, sarcoïdose</td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuses</strong></td>\n            <td>Ténosynovites d’inoculation (<span class=\"kw-clinique\">phlegmon</span> des gaines) : <span class=\"kw-etio\">staphylocoque</span>, pasteurellose, mycobactéries atypiques, <span class=\"kw-clinique\">gonocoque</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Facteurs détaillés depuis la fiche source (Tendinopathie, Bursite).</em></p>","frequence":0},{"id":"361-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisant d’une bursopathie","contenu":"<p><span class=\"kw-clinique\">Les</span> causes d’une <span class=\"kw-def\">bursopathie</span> dépendent essentiellement des gestes effectués au quotidien (prédominance masculine).</p>\n      <ul>\n        <li><strong>Activité physique répétée</strong> (sportive ou professionnelle) avec gestes/mouvements répétés :\n          <ul>\n            <li><span class=\"kw-etio\">Professions</span> : <span class=\"kw-etio\">carreleurs</span>, <span class=\"kw-etio\">peintres</span>, artisans travaillant à genou, employés de bureau</li>\n            <li><span class=\"kw-etio\">Sports</span> : <span class=\"kw-etio\">coureurs</span>, <span class=\"kw-etio\">tennismen</span>, judokas, rugbymen, hockeyeurs</li>\n          </ul>\n        </li>\n        <li><strong>Pathologies chroniques favorisantes</strong> : <span class=\"kw-etio\">goutte</span>, <span class=\"kw-etio\">pseudo-goutte</span> / rhumatisme à microcristaux, <span class=\"kw-etio\">polyarthrite rhumatoïde</span>, <span class=\"kw-etio\">infection</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Localisations préférentielles.</strong>\n        <ul>\n          <li>Majoritaires : <strong><span class=\"kw-clinique\">épaules</span></strong> (sous-acromiale), <strong><span class=\"kw-clinique\">coudes</span></strong> (olécrane), <strong><span class=\"kw-clinique\">hanches</span></strong> (moyen fessier), <strong><span class=\"kw-clinique\">genoux</span></strong> (pré-rotulienne, patte d’oie)</li>\n          <li>Plus rares : cheville, pied, région du tendon calcanéen (rétro-calcanéenne)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Ponction</span> — précaution.</strong> Réalisée en cas de <span class=\"kw-clinique\">fièvre</span> (analyse cytobactériologique + microcristaux en lumière polarisée). <strong>Éviter de ponctionner un <span class=\"kw-def\">hygroma</span></strong> sauf suspicion septique (risque théorique d’inoculer la bourse).</div>","frequence":0},{"id":"361-4","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence d’une bursite","contenu":"<div class=\"callout callout-danger\"><strong>🔥 <span class=\"kw-alerte\">Urgence</span> = bursite septique.</strong> La présentation n’est <strong>pas</strong> spécifique d’une cause septique : la <span class=\"kw-clinique\">fièvre</span> est inconstante (<span class=\"kw-chiffre\">20–75 %</span> des cas). Toute bursite peut être infectée → la repérer avant tout geste.</div>\n\n      <table >\n        <thead><tr><th>Élément</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Localisations</strong></td>\n            <td>Bursites septiques <strong>superficielles</strong> : <span class=\"kw-clinique\">fréquentes</span><br>Bursites septiques <strong>profondes</strong> : rares, source de <span class=\"kw-alerte\">retard diagnostique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>Superficielle : signes inflammatoires locaux (<span class=\"kw-clinique\">tuméfaction</span> de la bourse, <span class=\"kw-clinique\">érythème</span>, <span class=\"kw-clinique\">chaleur</span>), douleur, gêne ; <span class=\"kw-clinique\">adénopathie</span> possible<br>Profonde : examen peu spécifique, dépend de la localisation</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>Superficielle : <span class=\"kw-imagerie\">RX</span> + <span class=\"kw-imagerie\">échographie</span> (guide la <span class=\"kw-ttt\">ponction</span>)<br>Profonde : <span class=\"kw-imagerie\">TDM</span> et/ou <span class=\"kw-imagerie\">IRM</span> (épanchement bursal, <span class=\"kw-clinique\">abcès</span>, atteinte osseuse)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Ponction</span></strong></td>\n            <td>Confirme l’origine septique : <span class=\"kw-bio\">leucocytes &gt; 10⁶/mL</span> très évocateur (Se <span class=\"kw-chiffre\">95 %</span>, Sp <span class=\"kw-chiffre\">80 %</span>). Germe principal : <span class=\"kw-alerte\">Staphylococcus aureus</span> (<span class=\"kw-chiffre\">80 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td><span class=\"kw-ttt\">Antibiothérapie probabiliste</span> après prélèvements (<span class=\"kw-ttt\">augmentin</span> / C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span>G</span>, <span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span>) ; <span class=\"kw-ttt\">chirurgie</span> si forme réfractaire ou récidivante</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"361-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques diagnostiques d’une tendinopathie","contenu":"<div class=\"obj-callout success\"><strong>Triade clinique de la tendinopathie</strong> (testing musculo-tendineux) — le diagnostic est <strong>clinique</strong>. Si <span class=\"kw-clinique\">les</span> 3 signes sont réunis, c’est une tendinopathie :\n        <ul>\n          <li>Douleur à la <span class=\"kw-clinique\">palpation</span> de l’insertion ou du corps tendineux</li>\n          <li>Douleur à la <span class=\"kw-clinique\">contraction contrariée</span> (contre résistance) du muscle</li>\n          <li>Douleur à l’<span class=\"kw-clinique\">étirement</span> passif du tendon</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>Signe négatif clé.</strong> La <strong>mobilisation douce passive</strong> de l’articulation est <span class=\"kw-clinique\">indolore</span> ❌ — c’est ce qui sépare la tendinopathie d’une atteinte articulaire.</div>\n\n      <p><strong>Présentation</strong> : <span class=\"kw-clinique\">douleur</span> qui se répète <span class=\"kw-clinique\">toujours dans les mêmes conditions</span> ; l’interrogatoire précise <span class=\"kw-clinique\">ancienneté</span>, <span class=\"kw-etio\">geste déclencheur</span>, horaire (fin de journée <span class=\"kw-bio\">vs</span> matin).</p>\n\n      <p style=\"margin-top:14px\"><strong><span class=\"kw-def\">Stadification</span></strong> (gravité croissante = traitement plus difficile) :</p>\n      <ul>\n        <li><span class=\"kw-def\">Stade 1</span> : <span class=\"kw-clinique\">douleur après l’effort</span></li>\n        <li><span class=\"kw-def\">Stade 2</span> : <span class=\"kw-clinique\">douleur pendant l’effort</span>, sans l’arrêter</li>\n        <li><span class=\"kw-def\">Stade 3</span> : <span class=\"kw-clinique\">douleur qui impose d’arrêter</span> l’effort</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Imagerie (1<sup>re</sup> intention).</strong> <span class=\"kw-imagerie\">Radiographie</span> de l’articulation douloureuse : recherche un facteur favorisant, une <span class=\"kw-imagerie\">calcification tendineuse</span>, un <span class=\"kw-def\">diagnostic différentiel</span>. <span class=\"kw-imagerie\">Échographie</span> et <span class=\"kw-imagerie\">IRM</span> (gold standard) en 2<sup>e</sup> intention : doute diagnostique ou résistance au traitement.</div>","frequence":2},{"id":"361-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","contenu":"<div class=\"callout callout-info\"><strong>Deux luxations à connaître.</strong> La <span class=\"kw-def\">luxation gléno-humérale</span> (antérieure dans <span class=\"kw-chiffre\">95 %</span> des cas) et la <span class=\"kw-def\">luxation/disjonction acromio-claviculaire</span> (chute sur le moignon de l’épaule).</div>\n\n      <p><strong>1. Luxation gléno-humérale antérieure (antéro-interne)</strong></p>\n      <ul>\n        <li><strong>Mécanisme</strong> : indirect, <span class=\"kw-etio\">chute sur la main/le coude</span> bras en <span class=\"kw-clinique\">abduction–rotation externe–rétropulsion</span> ; <span class=\"kw-def\">terrain</span> jeune sportif ou hyperlaxité</li>\n        <li><strong>Inspection</strong> (signes cliniques diagnostiques) :\n          <ul>\n            <li><span class=\"kw-clinique\">Signe de l’épaulette</span> (saillie de l’acromion)</li>\n            <li><span class=\"kw-clinique\">Coup de hache externe</span></li>\n            <li><span class=\"kw-clinique\">Vacuité de l’espace sous-acromial</span> ; saillie de la tête humérale dans le sillon delto-pectoral</li>\n            <li>Attitude vicieuse irréductible en abduction–rotation externe (<span class=\"kw-clinique\">signe de Berger</span>)</li>\n          </ul>\n        </li>\n        <li><strong>Imagerie</strong> <em>(systématique avant toute <span class=\"kw-ttt\">réduction</span>)</em> : <span class=\"kw-imagerie\">RX face</span> + <span class=\"kw-imagerie\">profil de Lamy</span> (profil d’omoplate) ± <span class=\"kw-def\">incidence</span> de Garth → tête en avant de la glène, <span class=\"kw-alerte\">rupture</span> du cintre scapulo-huméral</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>🚩 Complications de la luxation gléno-humérale</strong> (préciser l’heure de l’observation) :\n        <ul>\n          <li><span class=\"kw-alerte\">Nerveuse ++</span> (surtout &gt;<span class=\"kw-chiffre\"> 40 ans</span>) : <strong>nerf axillaire</strong> (sensibilité du moignon de l’épaule) ; nerf radial ; plexus brachial (luxation intra-coracoïdienne)</li>\n          <li><span class=\"kw-alerte\">Vasculaire</span> (exceptionnelle) : <strong><span class=\"kw-clinique\">abolition des pouls</span></strong> → <span class=\"kw-ttt\">réduction</span> immédiate</li>\n          <li><strong>Osseuses</strong> : <span class=\"kw-imagerie\">encoche de Malgaigne / Hill-Sachs</span> (tête), fracture du <span class=\"kw-imagerie\">tubercule majeur (trochiter)</span>, éculement de la glène (<span class=\"kw-imagerie\">Bankart osseux</span>)</li>\n          <li><strong>Tendineuse</strong> : <span class=\"kw-alerte\">rupture de la coiffe</span> (supra-épineux) — à évoquer systématiquement chez le &gt;<span class=\"kw-chiffre\"> 45 ans</span></li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\"><strong>⚠️ Luxation postérieure d'épaule — piège classique.</strong>\n        <ul>\n          <li><strong>Rare</strong> (<span class=\"kw-chiffre\">2–4 %</span> des luxations d'épaule), <span class=\"kw-alerte\">souvent méconnue sur la RX de face</span></li>\n          <li><strong>Contextes évocateurs</strong> : <span class=\"kw-etio\">crise comitiale</span>, <span class=\"kw-etio\">électrisation</span>, chute avec bras en <span class=\"kw-clinique\">rotation interne–adduction</span></li>\n          <li><strong>Attitude</strong> : bras <span class=\"kw-clinique\">bloqué en rotation interne</span>, en adduction</li>\n          <li><strong>Signe clinique</strong> : <span class=\"kw-clinique\">signe du coucher de soleil</span> (tête humérale postérieure ronde, <span class=\"kw-clinique\">coracoïde saillante en avant</span>)</li>\n          <li><strong>Imagerie</strong> : RX face <strong>+ profil axillaire de Lamy indispensable</strong> — la face peut être normale (« <span class=\"kw-imagerie\">signe de l'ampoule</span> » = tête humérale en rotation interne fixe, symétrique)</li>\n        </ul>\n      </div>\n\n\n      <p style=\"margin-top:14px\"><strong>2. Disjonction acromio-claviculaire</strong> — <span class=\"kw-def\">classification</span> de <span class=\"kw-def\">Rockwood</span> (sévérité l<span class=\"kw-chiffre\">iga</span>mentaire croissante)</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Lésions</th><th>Touche de piano</th><th>Tiroir A-P</th><th>Déformation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td><span class=\"kw-clinique\">Entorse</span> des l<span class=\"kw-chiffre\">iga</span>ments acromio-claviculaires</td><td>❌</td><td>❌</td><td>❌</td></tr>\n          <tr><td><strong>2</strong></td><td><span class=\"kw-alerte\">Rupture</span> des l<span class=\"kw-chiffre\">iga</span>ments <strong>acromio-claviculaires</strong></td><td>Modérée</td><td>❌</td><td>❌</td></tr>\n          <tr><td><strong>3</strong></td><td><span class=\"kw-def\">Stade</span> 2 + <span class=\"kw-alerte\">rupture</span> des l<span class=\"kw-chiffre\">iga</span>ments <strong>coraco-claviculaires</strong> (trapézoïde, conoïde)</td><td>✅</td><td>✅</td><td>Modérée</td></tr>\n          <tr><td><strong>4</strong></td><td><span class=\"kw-def\">Stade</span> 3 + <span class=\"kw-alerte\">rupture</span> de la <strong>chape delto-trapézienne</strong></td><td>✅ (parfois fixée)</td><td>✅</td><td>✅</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Clinique</strong> : douleur élective à la palpation de l’extrémité distale de la clavicule, <span class=\"kw-clinique\">mobilité en touche de piano</span> (verticale), tiroir antéro-postérieur (<span class=\"kw-def\">stade</span> 3-4)</li>\n        <li><strong>Imagerie</strong> : <span class=\"kw-imagerie\">RX face centrée</span> sur l’acromio-claviculaire + <span class=\"kw-imagerie\">profil de Lamy</span> + <span class=\"kw-imagerie\">profil axillaire</span> ; clichés comparatifs en charge si doute</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Lésions associées ⚠️.</strong> <span class=\"kw-alerte\">Lésions du plexus brachial</span> (abaissement du moignon) ; lésions complexes de la ceinture scapulaire (syndrome omo-cléido-thoracique). Au <span class=\"kw-def\">stade</span> 4 : perforations cutanées possibles, irréductibilité.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/anterior-shoulder-dislocation","label":"Radiopaedia : luxation antérieure d’épaule"},{"href":"https://radiopaedia.org/articles/acromioclavicular-joint-1","label":"Radiopaedia : articulation acromio-claviculaire"},{"href":"https://radiopaedia.org/articles/rockwood-classification-of-acromioclavicular-joint-injury","label":"Radiopaedia : classification de Rockwood"}]},{"id":"361-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence d’une tendinopathie de la coiffe des rotateurs","contenu":"<div class=\"callout callout-danger\"><strong>🔥 Deux situations urgentes / hyperalgiques de la coiffe.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Épaule aiguë hyperalgique</span> par <span class=\"kw-etio\">résorption de calcification</span> (<span class=\"kw-etio\">rhumatisme à hydroxyapatite</span>) : <span class=\"kw-clinique\">douleur brutale</span>, intense, <span class=\"kw-clinique\">diurne et nocturne</span>, sur <span class=\"kw-def\">tendinopathie calcifiante</span></li>\n          <li><span class=\"kw-alerte\">Rupture massive aiguë de la coiffe</span> donnant un tableau <strong>« pseudo-paralytique »</strong> : <span class=\"kw-clinique\">impotence sévère</span> avec mobilités <strong>passives conservées</strong> — surtout après <span class=\"kw-etio\">traumatisme</span> chez le sujet de <span class=\"kw-chiffre\">&gt; 45 ans</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>Piège — ne pas confondre épaule aiguë hyperalgique et arthrite septique.</strong> Devant une épaule aiguë très douloureuse, éliminer une <span class=\"kw-alerte\">arthrite septique</span> (<span class=\"kw-alerte\">urgence</span>) : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">rougeur</span> → <strong><span class=\"kw-ttt\">ponction</span> articulaire</strong>. <span class=\"kw-clinique\">Les</span> autres causes d’épaule aiguë : <span class=\"kw-etio\">arthrite microcristalline</span> (chondrocalcinose), <span class=\"kw-etio\">arthrite inflammatoire</span>.</div>\n\n      <p>La résorption de calcification est fréquente dans la <span class=\"kw-def\">tendinite calcifiante de la coiffe</span> : la dissolution des dépôts calciques provoque une douleur <span class=\"kw-etio\">inflammatoire</span> aiguë.</p>\n      <div class=\"callout callout-info\"><strong>CAT.</strong> <span class=\"kw-ttt\">Antalgiques / anti-inflammatoires</span> pour <span class=\"kw-clinique\">les</span> formes non infectieuses ; <span class=\"kw-ttt\">ponction articulaire</span> si suspicion septique. À part : <span class=\"kw-ttt\">ponction</span>-lavage-aspiration d’une calcification.</div>","frequence":2},{"id":"361-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une tendinopathie de la coiffe des rotateurs","contenu":"<div class=\"callout callout-info\"><strong>Coiffe des rotateurs = 4 tendons + le long biceps (hors coiffe).</strong>\n        <ul>\n          <li><span class=\"kw-def\">Supra-épineux</span> → abduction (testé par <strong>Jobe</strong>)</li>\n          <li><span class=\"kw-def\">Infra-épineux</span> + <span class=\"kw-def\">teres minor</span> → rotation externe (Patte, portillon, clairon)</li>\n          <li><span class=\"kw-def\">Subscapulaire</span> → rotation interne (Lift-off / Gerber, Belly-press, Bear-hug)</li>\n          <li><span class=\"kw-def\">Long biceps</span> → palm-up test de Gilcreest (ne fait pas partie de la coiffe)</li>\n        </ul>\n      </div>\n\n      <p><strong>Démarche clinique.</strong> Mobilisation <strong>active</strong> (recherche un déficit + amplitudes), puis <strong>passive</strong> (raideur, douleur, conflit). Le couple <em>conflit <span class=\"kw-bio\">vs</span> déficit</em> oriente le diagnostic :</p>\n      <table >\n        <thead><tr><th>Type d’atteinte</th><th>Testing et signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Manœuvres de conflit</strong> (souffrance de la coiffe)</td>\n            <td><strong>Neer</strong> ; <strong>Hawkins</strong> ; <strong>Yocum</strong> ; <strong>Cross-arm</strong> — recherchent un <span class=\"kw-clinique\">conflit sous-acromial</span> (douleur entre 60–120°)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Tendinopathie simple</span></strong> (non rompue)</td>\n            <td>Douleur <span class=\"kw-clinique\">mécanique</span> à l’effort / élévation au-dessus de l’horizontale ; test tendineux <strong>douloureux mais NON déficitaire</strong> ❌ ; amplitudes conservées<br><span class=\"kw-imagerie\">RX normale</span> ; <span class=\"kw-imagerie\">échographie</span> : bursite, tendinite</td>\n          </tr>\n          <tr>\n            <td><strong>Tendinopathie calcifiante</strong></td>\n            <td>Douleur aiguë diurne <strong>et nocturne</strong> ; test non déficitaire<br><span class=\"kw-imagerie\">RX : calcification intra-tendineuse</span> +++</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rupture de la coiffe</span></strong></td>\n            <td>Test tendineux <strong>douloureux ET déficitaire</strong> ; mobilité active déficitaire, <strong>passive conservée</strong> ; tendon le plus atteint = <span class=\"kw-def\">supra-épineux</span> (Jobe +)<br>Signes : atrophie des fosses, <span class=\"kw-clinique\">signe de Popeye</span> (<span class=\"kw-alerte\">rupture</span> long biceps)<br><span class=\"kw-imagerie\">RX</span> : ascension de la tête (signe tardif) ; <span class=\"kw-imagerie\">échographie</span> confirme ; <span class=\"kw-imagerie\">IRM/arthroscanner</span> si projet chirurgical</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges du déficit.</strong> Le déficit peut être <strong>difficile à interpréter</strong> (parfois seulement <span class=\"kw-ttt\">antalgique</span>) et <strong>manquer</strong> dans <span class=\"kw-clinique\">les</span> ruptures chroniques (compensation par les autres muscles). Piège d’annale : une atteinte du <strong>côté dominant n’oriente PAS</strong> vers une origine professionnelle (le membre dominant est toujours plus sollicité).</div>","frequence":3,"liens":[{"href":"https://radiologyassistant.nl/musculoskeletal/shoulder/rotator-cuff-injury","label":"Radiology Assistant : atteinte de la coiffe"},{"href":"https://radiopaedia.org/articles/supraspinatus-tendon-tear","label":"Radiopaedia : rupture du supra-épineux"}]},{"id":"361-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les quatre présentations de lésions périarticulaires et ligamentaires de l’épaule","contenu":"<div class=\"obj-callout success\"><strong>Quatre grandes présentations de l’épaule.</strong> Deux <span class=\"kw-def\">péri-articulaires</span> (tendineuses/capsulaires) et deux <span class=\"kw-def\">ligamentaires</span> (instabilité/disjonction).</div>\n\n      <table >\n        <thead><tr><th>Présentation</th><th>Caractéristiques cliniques clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-def\">Tendinopathie / rupture de la coiffe des rotateurs</span></strong><br><em>(péri-articulaire)</em></td>\n            <td>Douleur mécanique, recrudescence <span class=\"kw-clinique\">nocturne</span> ; test tendineux douloureux (± déficitaire si <span class=\"kw-alerte\">rupture</span>) ; conflit sous-acromial ; mobilité passive conservée</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Capsulite rétractile</span></strong> (épaule gelée)<br><em>(péri-articulaire)</em></td>\n            <td>Limitation <strong>active ET passive</strong> (surtout <span class=\"kw-clinique\">RE1</span> souvent nulle) ; douleur diurne et <span class=\"kw-clinique\">nocturne</span> ; tests tendineux normaux ; <span class=\"kw-imagerie\">RX normale</span> (interligne conservé, <span class=\"kw-bio\">vs</span> omarthrose)</td>\n          </tr>\n          <tr>\n            <td><strong>3. <span class=\"kw-def\">Luxation gléno-humérale</span></strong> (instabilité)<br><em>(l<span class=\"kw-chiffre\">iga</span>mentaire)</em></td>\n            <td>Antérieure ++ (<span class=\"kw-chiffre\">95 %</span>) ; signe de l’épaulette, coup de hache, vacuité sous-acromiale ; lésions de <span class=\"kw-imagerie\">Bankart</span> / <span class=\"kw-imagerie\">Hill-Sachs</span> ; risque de récidive (sujet jeune)</td>\n          </tr>\n          <tr>\n            <td><strong>4. <span class=\"kw-def\">Disjonction acromio-claviculaire</span></strong><br><em>(l<span class=\"kw-chiffre\">iga</span>mentaire)</em></td>\n            <td>Chute sur le moignon ; douleur élective de la clavicule distale ; <span class=\"kw-clinique\">touche de piano</span> ; <span class=\"kw-def\">classification</span> de <span class=\"kw-def\">Rockwood</span> (stades 1–4)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Lecture clinique de l’épaule douloureuse</strong> — relier le syndrome à l’étiologie :\n        <ul>\n          <li><span class=\"kw-clinique\">Épaule raide</span> (active + passive ↓) → capsulite, algodystrophie, omarthrose évoluée</li>\n          <li><span class=\"kw-clinique\">Épaule fonctionnelle mais douloureuse</span> → conflit sous-acromial, calcification, <span class=\"kw-alerte\">rupture</span> partielle</li>\n          <li><span class=\"kw-clinique\">Épaule déficitaire</span> (perte de force ciblée) → <span class=\"kw-alerte\">rupture</span> de coiffe</li>\n          <li><span class=\"kw-alerte\">Épaule pseudo-paralytique</span> (impotence sévère, passif conservé) → <span class=\"kw-alerte\">rupture</span> massive de coiffe</li>\n          <li><span class=\"kw-alerte\">Épaule hyperalgique</span> → tendinopathie calcifiante (résorption)</li>\n        </ul>\n      </div>","frequence":5},{"id":"361-10","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","contenu":"<div class=\"obj-callout success\"><strong>Distinguer <span class=\"kw-clinique\">lésion</span> l<span class=\"kw-chiffre\">iga</span>mentaire (pivot central) <span class=\"kw-bio\">vs</span> lésion méniscale</strong> — l’orientation est clinique.</div>\n\n      <table >\n        <thead><tr><th></th><th>Atteinte ligamentaire (pivot central)</th><th>Atteinte méniscale</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td><span class=\"kw-clinique\">Laxité</span> (mouvements anormaux) ± <span class=\"kw-clinique\">instabilité</span> (sensation de lâchage / insécurité) ; <span class=\"kw-clinique\">épanchement</span> spontané ou à l’effort ; douleur</td>\n            <td>Douleur <span class=\"kw-clinique\">mécanique</span> face interne / postéro-médiale ; <span class=\"kw-clinique\">épanchement à l’effort</span> ; <span class=\"kw-alerte\">blocage méniscal</span> (douleur brutale + blocage de l’extension, flexion possible)</td>\n          </tr>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td>Sport de <span class=\"kw-etio\">pivot</span> (ski) ou <span class=\"kw-etio\">pivot-contact</span> (football) ; entorse en valgus/varus + rotation</td>\n            <td>Mouvement de <span class=\"kw-etio\">torsion en charge</span> ; relèvement d’une position accroupie</td>\n          </tr>\n          <tr>\n            <td><strong>Testing</strong></td>\n            <td><span class=\"kw-clinique\">Lachman</span> (arrêt mou = LCA, arrêt dur = LCP), <span class=\"kw-clinique\">ressaut rotatoire</span> (Jerk test, LCA), <span class=\"kw-clinique\">avalement de la TTA</span> + tiroir postérieur (LCP), laxité varus/valgus (LCL/LCM)</td>\n            <td>Douleur à la <span class=\"kw-clinique\">palpation de l’interligne</span> ; <span class=\"kw-clinique\">Grinding-test</span> (Apley) ; <span class=\"kw-clinique\">Mac Murray</span> (ressaut + douleur) ; signe de <span class=\"kw-clinique\">Genety</span> (flessum asymétrique en DV)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Pivot central — repères.</strong> <span class=\"kw-def\">LCA</span> s’oppose à la <strong>translation antérieure</strong> du tibia ; <span class=\"kw-def\">LCP</span> à la translation postérieure. La <strong>triade malheureuse de Trillat</strong> = <span class=\"kw-clinique\">LCA + ménisque médial + plan médial</span> (mécanisme valgus + flexion + rotation externe).</div>\n      <div class=\"callout callout-info\"><strong>Conséquence à connaître.</strong> Une <span class=\"kw-alerte\">rupture</span> du LCA augmente <span class=\"kw-clinique\">les</span> contraintes sur la corne postérieure du <span class=\"kw-clinique\">ménisque médial</span>, puis sur le cartilage → <span class=\"kw-alerte\">gonarthrose</span> secondaire.</div>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/meniscal-tear","label":"Radiopaedia : lésion méniscale"}]},{"id":"361-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les cinq principales présentations de lésions périarticulaires du genou","contenu":"<div class=\"obj-callout success\"><strong>Cinq lésions péri-articulaires du genou</strong> — quatre tendinopathies + une bursite. La localisation de la douleur fait le diagnostic.</div>\n\n      <table >\n        <thead><tr><th>Présentation</th><th>Localisation douleur</th><th>Tests / contexte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-def\">Tendinopathie rotulienne</span></strong><br><em>(la plus fréquente)</em></td>\n            <td><span class=\"kw-clinique\">Pôle inférieur</span> de la patella</td>\n            <td>Douleur à l’<span class=\"kw-clinique\">extension contre résistance</span> + <span class=\"kw-clinique\">flexion passive</span> ; sports de saut/impulsion (basket, volley) — « genou du sauteur »</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Tendinopathie quadricipitale</span></strong></td>\n            <td><span class=\"kw-clinique\">Pôle supérieur</span> de la patella</td>\n            <td>Douleur à l’extension contre résistance + à l’<span class=\"kw-clinique\">étirement passif</span> ; haltérophilie, efforts en charge</td>\n          </tr>\n          <tr>\n            <td><strong>3. <span class=\"kw-def\">Tendinopathie de la patte d’oie</span></strong></td>\n            <td>Face <span class=\"kw-clinique\">antéro-médiale</span> du genou, sous l’interligne</td>\n            <td>Douleur à la <span class=\"kw-clinique\">flexion + rotation interne contrariée</span> ; coureurs, <span class=\"kw-etio\">genu valgum</span>, femme &gt;<span class=\"kw-chiffre\"> 50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>4. <span class=\"kw-def\">Syndrome de la bandelette ilio-tibiale</span></strong> (fascia lata / essuie-glace)</td>\n            <td>Face <span class=\"kw-clinique\">latérale</span>, au condyle latéral</td>\n            <td><span class=\"kw-clinique\">Test de Noble</span> (tension du tractus à 30°) ; <span class=\"kw-clinique\">test de Renne</span> (appui monopodal) ; coureurs, cyclistes, <span class=\"kw-etio\">genu varum</span></td>\n          </tr>\n          <tr>\n            <td><strong>5. <span class=\"kw-def\">Bursite pré-rotulienne</span></strong> (hygroma)</td>\n            <td>En avant de la rotule</td>\n            <td><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-clinique\">fluctuante</span>, sensible ; douleur <strong>peu liée au mouvement</strong> ; <strong>absence de <span class=\"kw-alerte\">choc</span> rotulien</strong> ❌ (pas d’épanchement intra-articulaire) ; mobilité douce indolore</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>🚩 Ruptures tendineuses de l'appareil extenseur — à ne pas manquer.</strong>\n        <table>\n          <thead><tr><th>Rupture</th><th>Terrain</th><th>Signe clé</th><th>Imagerie</th></tr></thead>\n          <tbody>\n            <tr>\n              <td><strong><span class=\"kw-def\">Rupture du tendon quadricipital</span></strong></td>\n              <td>Sujet <span class=\"kw-clinique\">âgé &gt; 40 ans</span></td>\n              <td><span class=\"kw-clinique\">Patella basse</span> ; <span class=\"kw-clinique\">encoche sus-patellaire</span> palpable ; incapacité d'extension active</td>\n              <td><span class=\"kw-imagerie\">Échographie</span> / <span class=\"kw-imagerie\">IRM</span></td>\n            </tr>\n            <tr>\n              <td><strong><span class=\"kw-def\">Rupture du tendon rotulien</span></strong></td>\n              <td>Sujet <span class=\"kw-clinique\">jeune sportif</span></td>\n              <td><span class=\"kw-clinique\">Patella haute</span> (rétractée vers le haut) ; <span class=\"kw-alerte\">incapacité d'extension active</span></td>\n              <td><span class=\"kw-imagerie\">Échographie</span> / <span class=\"kw-imagerie\">IRM</span></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"callout callout-info\"><strong>Imagerie péri-articulaire du genou.</strong> 1<sup>re</sup> intention : <span class=\"kw-imagerie\">RX genou</span> (face en charge + profil) + <span class=\"kw-imagerie\">échographie</span> ; 2<sup>e</sup> intention (résistance / atypie) : <span class=\"kw-imagerie\">IRM</span>.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/patellar-tendinopathy","label":"Radiopaedia : tendinopathie patellaire"},{"href":"https://radiopaedia.org/articles/prepatellar-bursitis","label":"Radiopaedia : bursite pré-rotulienne"}]},{"id":"361-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les deux principales présentations de lésions périarticulaires de la cheville","contenu":"<div class=\"obj-callout success\"><strong>Deux présentations péri-articulaires de la cheville</strong> — une tendinopathie + une bursopathie, sur le complexe <span class=\"kw-def\">suro-achilléo-plantaire</span> (triceps sural → tendon calcanéen → calcanéus).</div>\n\n      <table >\n        <thead><tr><th>Présentation</th><th>Clinique et imagerie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-def\">Tendinopathie d’Achille (calcanéenne)</span></strong><br><em>cause la plus fréquente de talalgie postérieure,<span class=\"kw-chiffre\"> 30–50 %</span> des lésions du sport</em></td>\n            <td><span class=\"kw-clinique\">Talalgie postérieure</span> dans le corps du tendon, d’abord après l’effort puis constante (± nocturne, raideur matinale dans <span class=\"kw-clinique\">les</span> formes inflammatoires).<br>Douleur à la <span class=\"kw-clinique\">palpation</span>, à l’<span class=\"kw-clinique\">étirement</span> (dorsiflexion), à la <span class=\"kw-clinique\">contraction contrariée du triceps sural</span>.<br><span class=\"kw-alerte\">Rupture</span> : perte de substance + <span class=\"kw-clinique\">test de Thompson</span> positif (perte de flexion plantaire à la pression du mollet).<br>Diagnostic <strong>clinique</strong> ; <span class=\"kw-imagerie\">échographie comparative</span> si besoin ; cause mécanique (coureur) <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">inflammatoire</span> (spondylarthrite).</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-def\">Bursopathie rétro-calcanéenne</span></strong> (pré-achilléenne)</td>\n            <td>Bourse à l’<span class=\"kw-clinique\">angle postéro-supérieur du calcanéus</span> (entre calcanéus et tendon calcanéen).<br>Douleurs précises à la partie supérieure du calcanéus ; hypertrophie postérieure (<span class=\"kw-def\">maladie de Haglund</span>).<br>Étiologie <span class=\"kw-etio\">inflammatoire</span> (<span class=\"kw-etio\">spondyloarthrite</span>) ou mécanique (conflit ± Haglund).<br><span class=\"kw-imagerie\">RX profil</span> (forme du calcanéus, érosions) ; <span class=\"kw-imagerie\">échographie / IRM</span> (épanchement bursal).</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/achilles-tendinopathy","label":"Radiopaedia : tendinopathie d’Achille"},{"href":"https://radiopaedia.org/articles/retrocalcaneal-bursitis","label":"Radiopaedia : bursite rétro-calcanéenne"}]},{"id":"361-13","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","contenu":"<div class=\"obj-callout success\"><strong>1<sup>re</sup> intention = <span class=\"kw-imagerie\">RADIOGRAPHIE</span>.</strong> L’imagerie est guidée par la clinique. La radio est <strong>systématique</strong> en <span class=\"kw-chiffre\">première intention</span>.</div>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographies</span></strong> <em>(1<sup>re</sup> intention, systématique)</em></td>\n            <td>Clichés : <strong><span class=\"kw-imagerie\">épaule face 3 rotations</span></strong> + <strong><span class=\"kw-imagerie\">profil d’omoplate de Lamy</span></strong>.<br>Objectif : <strong>éliminer</strong> une <span class=\"kw-etio\">pathologie osseuse</span> (tumeur) ou articulaire (<span class=\"kw-def\">omarthrose primitive</span>) et chercher <span class=\"kw-clinique\">les</span> <strong>signes indirects</strong> :\n              <ul>\n                <li>Tendinopathie simple : <span class=\"kw-imagerie\">RX normale</span></li>\n                <li>Tendinopathie calcifiante : <span class=\"kw-imagerie\">calcifications intra-tendineuses</span> +++</li>\n                <li><span class=\"kw-alerte\">Rupture</span> : <span class=\"kw-imagerie\">condensation/géodes du trochiter</span>, enthésophyte acromial, <span class=\"kw-imagerie\">pincement sous-acromial &lt; 7 mm</span>, excentration céphalique (omarthrose excentrée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong> <em>(1<sup>re</sup> intention si doute / résistance)</em></td>\n            <td>Indiquée si <span class=\"kw-clinique\">doute de rupture</span> ou résistance au traitement (insuffisante pour l’indication opératoire) : <span class=\"kw-imagerie\">épaississement/désorganisation du tendon</span>, <span class=\"kw-imagerie\">rupture transfixiante</span>, <span class=\"kw-imagerie\">bursite</span>, état du biceps</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM / arthroscanner</span></strong> <em>(2<sup>e</sup> intention)</em></td>\n            <td>Réservés à l’<strong>échec du traitement médical</strong> chez un sujet jeune, quand une <span class=\"kw-ttt\">réparation chirurgicale</span> est envisagée (siège, étendue, rétraction, dégénérescence graisseuse)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère <span class=\"kw-imagerie\">échographie</span> / <span class=\"kw-imagerie\">IRM</span> (cf. tendinopathie en général).</strong> En 1<sup>re</sup> intention, hors épaule, la <span class=\"kw-imagerie\">RX</span> reste l’examen princeps (calcification, <span class=\"kw-def\">diagnostic différentiel</span>) ; l’<span class=\"kw-imagerie\">échographie</span> n’est sollicitée qu’en 3<sup>e</sup> intention dans le cadre d’une <strong>maladie professionnelle</strong>.</div>","frequence":2},{"id":"361-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication et l’intérêt des examens d’imagerie en première intention dans le cadre d’une capsulite rétractile","contenu":"<div class=\"obj-callout success\"><strong>Diagnostic clinique + normalité de la <span class=\"kw-imagerie\">radiographie</span>.</strong> Le diagnostic de <span class=\"kw-def\">capsulite rétractile</span> repose sur la <strong>clinique</strong> (<span class=\"kw-clinique\">limitation active et passive</span>, surtout <span class=\"kw-clinique\">RE1</span>) et la <strong>normalité de la <span class=\"kw-imagerie\">RX standard</span></strong>.</div>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographie standard</span></strong> <em>(1<sup>re</sup> intention)</em></td>\n            <td><span class=\"kw-imagerie\">Normale</span> : <span class=\"kw-imagerie\">interligne gléno-huméral conservé</span> ✅ — point clé pour la <strong>différencier de l’<span class=\"kw-def\">omarthrose</span></strong> (qui pince l’interligne)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td><strong>Pas d’intérêt</strong> ❌ (normale)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span></strong></td>\n            <td>À réserver en cas de <span class=\"kw-clinique\">doute diagnostique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Rappel clinique.</strong> <span class=\"kw-def\">Capsulite</span> = <span class=\"kw-clinique\">douleurs diurnes et nocturnes</span> ; limitation <strong>passive et active</strong> (<span class=\"kw-clinique\">RE1</span> souvent nulle, élévation antérieure <span class=\"kw-chiffre\">&lt; 90°</span>) ; tests tendineux normaux ✅. Elle entre dans le cadre des <span class=\"kw-def\">SDRC</span> (ex-algoneurodystrophie). <span class=\"kw-clinique\">Évolution</span> lente mais favorable (<span class=\"kw-chiffre\">18–24 mois</span>).</div>","frequence":0},{"id":"361-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication, l’intérêt et les objectifs des examens d’imagerie d’une lésion péri-articulaire et ligamentaire du genou","contenu":"<div class=\"callout callout-warn\"><strong>Ordre impératif : RADIO d’abord, bilan l<span class=\"kw-chiffre\">iga</span>mentaire / <span class=\"kw-imagerie\">IRM</span> ensuite.</strong> Le bilan ligamentaire clinique se fait <strong>uniquement après la <span class=\"kw-imagerie\">radiographie</span></strong> (vérifier l’absence de <span class=\"kw-clinique\">lésion</span> osseuse), toujours <strong>bilatéral et comparatif</strong>. L’<span class=\"kw-imagerie\">IRM ne se fait pas en urgence</span> mais à <span class=\"kw-chiffre\">2–3 semaines</span> du traumatisme.</div>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographies</span> des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>enoux</strong> <em>(1<sup>re</sup> intention, systématique)</em></td>\n            <td>Clichés : <strong>face + profil + fémoro-patellaire à 30°</strong> (défilé). Objectif = <strong>rechercher des lésions osseuses</strong> (l<span class=\"kw-chiffre\">iga</span>ments invisibles, seulement des signes <strong>indirects</strong>) :\n              <ul>\n                <li><span class=\"kw-imagerie\">Fracture de Segond</span> (« chips » corticale latérale) = pathognomonique d’une <span class=\"kw-alerte\">rupture</span> récente du <strong>LCA</strong></li>\n                <li><span class=\"kw-imagerie\">Avulsion de l’épine tibiale antérieure</span> (LCA) ; <span class=\"kw-imagerie\">arrachement de la surface rétro-spinale</span> (<strong>LCP</strong>)</li>\n                <li><span class=\"kw-imagerie\">Pellegrini-Stieda</span> (calcification du plan médial) = <span class=\"kw-alerte\">rupture</span> ancienne du <strong>LCM</strong></li>\n                <li><span class=\"kw-imagerie\">Pincements asymétriques</span> = <span class=\"kw-alerte\">arthrose</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> (séquences T2 fat-sat)</strong> <em>(en <span class=\"kw-alerte\">urgence</span> différée, 2–3 sem.)</em></td>\n            <td>Examen de référence des l<span class=\"kw-chiffre\">iga</span>ments : normalement en <span class=\"kw-imagerie\">hyposignal T2</span>, <span class=\"kw-clinique\">lésion</span> en <span class=\"kw-imagerie\">hypersignal T2</span> (échancrure de l’état anatomique). Bilan des lésions associées : <strong>ménisques</strong> (anse de seau), cartilage, <span class=\"kw-imagerie\">bone bruise</span> (contusion osseuse = signe indirect de <span class=\"kw-alerte\">rupture</span> du LCA)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RX méniscale</span></strong> (en charge F + Schuss + P + DFP 30°)</td>\n            <td><span class=\"kw-clinique\">Ménisque sain non visible</span> ; recherche une <span class=\"kw-alerte\">gonarthrose</span> (<span class=\"kw-imagerie\">pincement</span>). L’<span class=\"kw-imagerie\">IRM</span> est <strong>inutile si arthrose radiologique</strong> ; classe <span class=\"kw-clinique\">les</span> lésions (<span class=\"kw-imagerie\">grade 3</span> = atteinte de la surface = seule potentiellement symptomatique)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":3,"liens":[{"href":"https://radiologyassistant.nl/musculoskeletal/knee/meniscal-pathology","label":"Radiology Assistant : pathologie méniscale"}]},{"id":"361-16","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication et l’intérêt des examens d’imagerie devant une lésion péri-articulaire et ligamentaire de la cheville","contenu":"<div class=\"obj-callout success\"><strong>Si entorse isolée, <span class=\"kw-clinique\">les</span> radiographies sont NORMALES ✅.</strong> L’entorse est une <span class=\"kw-clinique\">lésion</span> l<span class=\"kw-chiffre\">iga</span>mentaire <strong>sans</strong> perte des rapports articulaires : la RX ne sert qu’à chercher les <strong>lésions associées</strong> ou un <span class=\"kw-def\">diagnostic différentiel</span> (fracture).</div>\n\n      <div class=\"callout callout-warn\"><strong>Indication des RX = critères d’Ottawa</strong> (<span class=\"kw-chiffre\">≥ 1</span> critère) :\n        <ul>\n          <li>Âge <span class=\"kw-chiffre\">&lt; 18 ans</span> ou <span class=\"kw-chiffre\">&gt; 55 ans</span></li>\n          <li>Douleur à la palpation du bord postérieur des <span class=\"kw-clinique\">malléoles</span> (sur <span class=\"kw-chiffre\">6 cm</span>)</li>\n          <li>Douleur à la base du <span class=\"kw-clinique\">5<sup>e</sup> métatarsien</span> ou de l’<span class=\"kw-clinique\">os naviculaire</span></li>\n          <li><span class=\"kw-clinique\">Impossibilité de faire 4 pas</span> en plein appui</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt / objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Incidence de Mortaise</span></strong> (face, rotation médiale 20°)</td>\n            <td>Recherche <span class=\"kw-imagerie\">bâillement articulaire</span>, <span class=\"kw-imagerie\">diastasis</span> talo-malléolaire ou de la syndesmose, <span class=\"kw-alerte\">fracture ostéochondrale du dôme du talus</span> (→ <span class=\"kw-imagerie\">TDM</span>), arrachements ostéo-périostés, fractures malléolaires peu déplacées</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Cliché de profil</span></strong></td>\n            <td><span class=\"kw-imagerie\">Hémarthrose</span> (refoulement de la ligne graisseuse) → évoque une fracture ostéochondrale du talus ; contrôle du parallélisme de l’interligne ; base du 5<sup>e</sup> métatarsien et naviculaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td>Examen d’avenir : affirme une <span class=\"kw-imagerie\">hémarthrose</span> (= signe de <strong>gravité</strong>), visualise la <span class=\"kw-alerte\">rupture</span> l<span class=\"kw-chiffre\">iga</span>mentaire et son étendue</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Imagerie en coupes</span></strong> (<span class=\"kw-imagerie\">TDM</span> / <span class=\"kw-imagerie\">IRM</span>)</td>\n            <td>Peu de place en <span class=\"kw-alerte\">urgence</span> : fractures <span class=\"kw-imagerie\">ostéochondrales</span> du talus (si hémarthrose), fracture du tubercule latéral du talus (piège d’une « entorse » par éversion)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Clichés dynamiques</span></strong></td>\n            <td><strong>Non en <span class=\"kw-alerte\">urgence</span></strong> ❌ : bilan d’instabilité chronique (laxité varus &gt; 10°, tiroir antérieur &gt;<span class=\"kw-chiffre\"> 8 mm</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>🚩 Piège du sujet âgé.</strong> Une « entorse » de cheville chez le sujet de <span class=\"kw-chiffre\">&gt; 60 ans</span> est rarissime : elle doit faire chercher une <span class=\"kw-alerte\">fracture malléolaire</span> (l’os fragile casse avant que le l<span class=\"kw-chiffre\">iga</span>ment ne cède).</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/lateral-ankle-sprain","label":"Radiopaedia : entorse latérale de cheville"}]},{"id":"361-17","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie avec entorse grave de cheville","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/361/radio-entorse-grave-cheville.png\" alt=\"Radiographies de la cheville droite (incidences de face et de profil) montrant les signes d’entorse grave : diastasis tibio-fibulaire distal, diastasis talo-tibial, épaississement des parties molles péri-malléolaires et fracture postérieure du pilon tibial.\" loading=\"lazy\">\n        <figcaption>Entorse grave de cheville droite (face + profil). Signes recherchés : <strong><span class=\"kw-imagerie\">diastasis tibio-fibulaire distal</span></strong>, <strong><span class=\"kw-imagerie\">diastasis talo-tibial</span></strong>, <strong><span class=\"kw-imagerie\">épaississement des parties molles péri-malléolaires</span></strong>, et <span class=\"kw-alerte\">fracture postérieure du pilon tibial</span>. Source : banque <em>Imagerie à connaître EDN</em>, item 361 (p. 87).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-info\"><strong>Lecture de la radio.</strong> En cas d’entorse <strong>isolée</strong>, la radio est <span class=\"kw-imagerie\">normale</span> ✅. Ici la gravité est affirmée par <span class=\"kw-clinique\">les</span> signes <strong>osseux et articulaires associés</strong> visibles sur les incidences de <span class=\"kw-imagerie\">face (Mortaise)</span> et de <span class=\"kw-imagerie\">profil</span>.</div>\n      <ul>\n        <li><span class=\"kw-imagerie\">Diastasis tibio-fibulaire distal</span> : atteinte de la syndesmose</li>\n        <li><span class=\"kw-imagerie\">Diastasis talo-tibial médial</span> : bâillement de l’interligne (perte du parallélisme)</li>\n        <li><span class=\"kw-imagerie\">Épaississement des parties molles</span> péri-malléolaires (<span class=\"kw-clinique\">œdème</span> / hématome)</li>\n        <li><span class=\"kw-alerte\">Fracture postérieure du pilon tibial</span> : <span class=\"kw-clinique\">lésion</span> osseuse associée</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Signes cliniques de gravité associés</strong> (rappel) : <span class=\"kw-clinique\">craquement</span>, <span class=\"kw-clinique\">impotence fonctionnelle totale</span> immédiate, <span class=\"kw-alerte\">hématome en « œuf de pigeon »</span> pré- et sous-malléolaire latéral, <span class=\"kw-clinique\">tiroir talien antérieur</span>, <span class=\"kw-clinique\">bâillement tibio-talien latéral</span>.</div>","frequence":1},{"id":"361-18","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie devant une luxation antéro-inférieure d’épaule","contenu":"<div class=\"callout callout-warn\"><strong>Imagerie systématique AVANT toute tentative de <span class=\"kw-ttt\">réduction</span></strong> — clichés ne demandant <strong>aucune mobilisation douloureuse</strong>.</div>\n\n      <table >\n        <thead><tr><th>Temps</th><th>Imagerie et objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span class=\"kw-ttt\">réduction</span></strong></td>\n            <td><span class=\"kw-imagerie\">Cliché de face</span> (pas <span class=\"kw-clinique\">les</span> 3 rotations : douloureux et de toute façon irréductible) + <span class=\"kw-imagerie\">profil scapulaire de Lamy</span> (profil d’omoplate) ± <span class=\"kw-imagerie\">incidence de Garth</span>.<br>Objectif : confirmer la luxation (<span class=\"kw-imagerie\">tête en avant de la glène</span>, <span class=\"kw-imagerie\">vacuité glénoïdienne</span>, <span class=\"kw-imagerie\">rupture du cintre scapulo-huméral</span>) et dépister les <strong>lésions osseuses associées</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Après <span class=\"kw-ttt\">réduction</span></strong></td>\n            <td><span class=\"kw-imagerie\">Bilan radiographique de contrôle</span> (face, profil de Lamy, Garth) : <strong>vérifier la <span class=\"kw-ttt\">réduction</span></strong> et déceler une <span class=\"kw-clinique\">lésion</span> osseuse mieux visible après réduction :\n              <ul>\n                <li><span class=\"kw-imagerie\">Encoche de Malgaigne / Hill-Sachs</span> (tête humérale)</li>\n                <li>Fracture du <span class=\"kw-imagerie\">tubercule majeur</span> ; <span class=\"kw-imagerie\">Bankart osseux</span> (rebord antéro-inférieur de la glène)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> / arthroscanner</strong></td>\n            <td>Demandé en cas de <strong>fracture associée</strong> ; l’<span class=\"kw-imagerie\">arthroscanner / arthro-IRM</span> évalue <span class=\"kw-clinique\">les</span> lésions ostéo-capsulo-labrales dans le bilan d’instabilité (récidive)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>🚩 Avant ET après <span class=\"kw-ttt\">réduction</span> : examen vasculo-nerveux.</strong> Tester le <span class=\"kw-alerte\">nerf axillaire</span> (<span class=\"kw-clinique\">sensibilité du moignon</span>) et <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">pouls périphériques</span>.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/hill-sachs-defect","label":"Radiopaedia : encoche de Hill-Sachs"},{"href":"https://radiopaedia.org/articles/bankart-lesion","label":"Radiopaedia : lésion de Bankart"}]},{"id":"361-19","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie avec luxation antéro-inférieure de l’épaule","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/361/radio-luxation-antero-inferieure-epaule.png\" alt=\"Radiographie de l’épaule gauche de face montrant une luxation antéro-inférieure : perte de contact entre la tête humérale et la glène, glène vide, tête humérale se projetant sous le processus coracoïde.\" loading=\"lazy\">\n        <figcaption><span class=\"kw-def\">Luxation antéro-inférieure de l’épaule</span> gauche (<span class=\"kw-def\">incidence</span> de face). Repères : <strong><span class=\"kw-imagerie\">acromion</span></strong>, <strong><span class=\"kw-imagerie\">processus coracoïde</span></strong>, <strong><span class=\"kw-imagerie\">glène (vide)</span></strong>. Source : banque <em>Imagerie à connaître EDN</em>, item 361 (p. 88).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-info\"><strong>Lecture de la radio (face).</strong>\n        <ul>\n          <li><span class=\"kw-imagerie\">Perte de contact</span> entre la tête humérale et la glène scapulaire</li>\n          <li><span class=\"kw-imagerie\">Glène vide</span>, <span class=\"kw-imagerie\">tête humérale se projetant sous le processus coracoïde</span></li>\n          <li><span class=\"kw-imagerie\">Superposition de la tête et du rebord inférieur de la glène</span></li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>Toujours rechercher un <span class=\"kw-imagerie\">trait de fracture</span> associé :</strong>\n        <ul>\n          <li><span class=\"kw-imagerie\">Encoche de Hill-Sachs</span> (impaction de la tête contre le rebord glénoïdien)</li>\n          <li><span class=\"kw-imagerie\">Fracture du rebord antéro-inférieur de la glène</span> = <span class=\"kw-clinique\">lésion</span> de <span class=\"kw-imagerie\">Bankart</span></li>\n        </ul>\n      </div>\n      <p>Cliniquement, cette luxation se traduit par le <span class=\"kw-clinique\">signe de l’épaulette</span>, le <span class=\"kw-clinique\">coup de hache externe</span>, la <span class=\"kw-clinique\">vacuité sous-acromiale</span> et la <span class=\"kw-clinique\">saillie de la tête sous la coracoïde</span>.</p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/anterior-shoulder-dislocation","label":"Radiopaedia : luxation antérieure d’épaule"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Luxation gléno-humérale :</strong> <span class=\"kw-ttt\">réduction</span> en <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-alerte\">immédiate si abolition des pouls</span> (compression vasculaire) ; examen <span class=\"kw-clinique\">vasculo-nerveux</span> (<span class=\"kw-etio\">nerf axillaire</span>) noté avant ET après, en <span class=\"kw-chiffre\">précisant l'heure</span> de l'observation<br><strong>Luxation vraie du genou :</strong> <span class=\"kw-alerte\">urgence vraie</span> — <span class=\"kw-ttt\">réduction sous sédation</span> puis <span class=\"kw-imagerie\">angioTDM</span> systématique (<span class=\"kw-etio\">lésion de l'artère poplitée</span> dans <span class=\"kw-chiffre\">5-10 %</span>) ; toute <span class=\"kw-alerte\">ischémie</span> impose une <span class=\"kw-ttt\">revascularisation</span> en <span class=\"kw-alerte\">urgence</span><br><strong>Bursite septique :</strong> <span class=\"kw-ttt\">ponction</span> du liquide bursal puis <span class=\"kw-ttt\">antibiothérapie probabiliste</span> après prélèvements bactériologiques<br><strong>Genou — fenêtre chirurgicale :</strong> <span class=\"kw-etio\">LCA</span> + <span class=\"kw-alerte\">lésion ligamentaire grave périphérique</span> ou <span class=\"kw-etio\">anse de seau</span> méniscale → <span class=\"kw-ttt\">chirurgie</span> idéale à <span class=\"kw-chiffre\">< 21 jours</span></p>","hospit":"<p><strong>Ambulatoire (ville + kinésithérapie) :</strong> la majorité des <span class=\"kw-etio\">tendinopathies</span>, <span class=\"kw-etio\">bursopathies</span> et <span class=\"kw-etio\">entorses bénignes ou moyennes</span> — <span class=\"kw-ttt\">repos relatif, antalgiques, rééducation</span><br><strong>Urgences traumatologiques :</strong> <span class=\"kw-etio\">luxation d'épaule</span>, <span class=\"kw-etio\">disjonction acromio-claviculaire</span>, <span class=\"kw-etio\">entorse grave</span> ou traumatisme du <span class=\"kw-etio\">genou</span> pour <span class=\"kw-imagerie\">imagerie</span> + <span class=\"kw-ttt\">réduction / immobilisation</span><br><strong>Avis orthopédique / <span class=\"kw-alerte\">hospitalisation</span> :</strong> <span class=\"kw-etio\">fracture associée</span>, <span class=\"kw-etio\">luxation du genou</span>, <span class=\"kw-alerte\">arthrite ou bursite septique</span>, ou échec du traitement médical (projet chirurgical)<br><strong>Bloc opératoire :</strong> <span class=\"kw-ttt\">réduction sous anesthésie générale</span> si <span class=\"kw-etio\">irréductibilité</span>, <span class=\"kw-etio\">fracture associée</span> ou <span class=\"kw-etio\">luxation intra-coracoïdienne</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Abolition des pouls périphériques</span> ou <span class=\"kw-clinique\">déficit sensitivo-moteur</span> (atteinte du <span class=\"kw-etio\">nerf axillaire</span>) après une <span class=\"kw-etio\">luxation gléno-humérale</span></li><li><span class=\"kw-alerte\">Laxité importante d'emblée</span> (« trop belle laxité ») + <span class=\"kw-clinique\">paralysie du nerf fibulaire commun</span> → <span class=\"kw-etio\">lésion multi-ligamentaire / luxation du genou</span> (risque d'<span class=\"kw-etio\">ischémie poplitée</span>)</li><li>Entorse de cheville : <span class=\"kw-clinique\">craquement audible</span>, <span class=\"kw-alerte\">appui impossible immédiat et persistant</span>, <span class=\"kw-radio\">hématome « oeuf de pigeon »</span>, <span class=\"kw-clinique\">tiroir talien antérieur</span> ou <span class=\"kw-clinique\">bâillement tibio-talien</span></li><li><span class=\"kw-clinique\">Fièvre</span> devant une bursite ou une arthrite → évoquer une <span class=\"kw-alerte\">cause septique</span> (<span class=\"kw-ttt\">ponction</span>)</li><li>Tableau <span class=\"kw-alerte\">pseudo-paralytique</span> aigu de l'épaule = <span class=\"kw-etio\">rupture massive de la coiffe</span></li><li>« Entorse » de cheville chez le sujet <span class=\"kw-chiffre\">> 60 ans</span> → rechercher une <span class=\"kw-etio\">fracture malléolaire</span> (entorse rarissime à cet âge)</li><li>Disjonction acromio-claviculaire <span class=\"kw-etio\">stade 4</span> : <span class=\"kw-alerte\">perforation cutanée</span>, <span class=\"kw-etio\">irréductibilité</span>, atteinte du <span class=\"kw-etio\">plexus brachial</span></li></ul>","principes":"<p>Traitement le plus souvent <span class=\"kw-ttt\">médical et fonctionnel</span> ; la <span class=\"kw-ttt\">chirurgie</span> est réservée aux <span class=\"kw-etio\">ruptures</span>, <span class=\"kw-etio\">instabilités</span> et <span class=\"kw-etio\">lésions graves ou déplacées</span>.</p><p><strong>Tendinopathie & bursite</strong></p><p>Bursite septique → <span class=\"kw-ttt\">ponction</span> + <span class=\"kw-ttt\">ATB probabiliste</span> (<span class=\"kw-ttt\">augmentin ou C1G</span>, <span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span>)</p><ul><li><span class=\"kw-ttt\">Repos relatif</span>, <span class=\"kw-ttt\">antalgiques</span> / <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">cryothérapie</span> en phase aiguë</li><li><span class=\"kw-ttt\">Rééducation</span> (étirements, renforcement <span class=\"kw-ttt\">excentrique</span>) ± <span class=\"kw-ttt\">infiltrations</span> sous contrôle écho/scopique</li><li><span class=\"kw-ci\">Éviter de ponctionner un hygroma</span> sauf suspicion septique (risque d'inoculation)</li></ul><p><strong>Luxation gléno-humérale</strong></p><p><span class=\"kw-ttt\">Réduction</span> <span class=\"kw-ttt\">sous AG</span> voire <span class=\"kw-ttt\">chirurgicale à ciel ouvert</span> si irréductibilité ou fracture associée</p><ul><li><span class=\"kw-ttt\">Réduction</span> (manoeuvre de <span class=\"kw-ttt\">Milch</span> ou <span class=\"kw-ttt\">Kocher</span>) sous <span class=\"kw-ttt\">sédation</span>, après <span class=\"kw-imagerie\">radiographie</span> pré-<span class=\"kw-ttt\">réduction</span></li><li><span class=\"kw-ttt\">Immobilisation coude au corps</span> : <span class=\"kw-chiffre\">3 semaines</span> (sujet âgé) à <span class=\"kw-chiffre\">6 semaines</span> (jeune à risque de récidive)</li><li><span class=\"kw-imagerie\">RX de contrôle</span> post-<span class=\"kw-ttt\">réduction</span> puis <span class=\"kw-ttt\">rééducation</span></li></ul><p><strong>Entorse de cheville (selon le <span class=\"kw-def\">stade</span>)</strong></p><p><span class=\"kw-ttt\">Thromboprophylaxie</span> si appui impossible ; <span class=\"kw-ttt\">chirurgie</span> réservée à l'instabilité chronique</p><ul><li><span class=\"kw-def\">Stade</span> 1 bénin → <span class=\"kw-ttt\">protocole RICE</span> pendant <span class=\"kw-chiffre\">3 jours</span></li><li><span class=\"kw-def\">Stade</span> 2 moyen → <span class=\"kw-ttt\">traitement fonctionnel</span> (<span class=\"kw-ttt\">strapping</span> / <span class=\"kw-ttt\">orthèse</span> ≥ <span class=\"kw-chiffre\">21 jours</span> + <span class=\"kw-ttt\">rééducation proprioceptive</span> <span class=\"kw-chiffre\">6 semaines</span>)</li><li><span class=\"kw-def\">Stade</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rave ou fracture → <span class=\"kw-ttt\">traitement orthopédique</span> (<span class=\"kw-ttt\">botte plâtrée</span> <span class=\"kw-chiffre\">6 semaines</span>)</li></ul><p><strong>Lésions l<span class=\"kw-chiffre\">iga</span>mentaires du genou</strong></p><p><span class=\"kw-ci\">Appui interdit 6 semaines</span> en cas d'atteinte associée du PAPI</p><ul><li><span class=\"kw-ttt\">Antalgiques</span> + <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">attelle de courte durée</span>, <span class=\"kw-ttt\">rééducation précoce</span></li><li><span class=\"kw-ci\">Chirurgie du LCA jamais avant le 3e mois</span> dans <span class=\"kw-clinique\">les</span> lésions isolées</li><li><span class=\"kw-ttt\">Ligamentoplastie</span> à <span class=\"kw-chiffre\">J15-J21</span> si <span class=\"kw-etio\">lésion grave périphérique</span>, <span class=\"kw-etio\">anse de seau</span> ou <span class=\"kw-etio\">luxation du genou</span></li></ul>","suivi":"<p><strong>Entorse de cheville :</strong> examen le plus <span class=\"kw-def\">spécifique</span> au <span class=\"kw-chiffre\">4e-5e jour</span> ; surveiller l'<span class=\"kw-etio\">instabilité chronique</span> (<span class=\"kw-chiffre\">10-30 %</span> des entorses graves ou négligées)<br><strong>Luxation d'épaule :</strong> <span class=\"kw-def\">réévaluation</span> clinique post-<span class=\"kw-ttt\">réduction</span> (<span class=\"kw-clinique\">pouls</span>, <span class=\"kw-clinique\">examen neurologique</span>), <span class=\"kw-imagerie\">RX de contrôle</span> ; dépister la <span class=\"kw-etio\">récidive</span> (sujet jeune) et la <span class=\"kw-etio\">capsulite rétractile</span> (âge mûr)<br><strong>Genou :</strong> <span class=\"kw-ci\">pas d'IRM en urgence</span> — <span class=\"kw-imagerie\">IRM</span> différée à <span class=\"kw-chiffre\">2-3 semaines</span> ; réévaluation au <span class=\"kw-chiffre\">3e mois</span> ; surveiller <span class=\"kw-etio\">instabilité</span> et <span class=\"kw-etio\">arthrose secondaire</span><br><strong>Tendinopathie :</strong> surveiller la <span class=\"kw-etio\">chronicisation</span> ; reprise du sport progressive selon la douleur</p>"},"liensGlobaux":[{"href":"https://radiologyassistant.nl/musculoskeletal/shoulder/mri-anatomy","label":"Radiology Assistant : anatomie IRM de l’épaule"},{"href":"https://radiopaedia.org/articles/shoulder","label":"Radiopaedia : anatomie de l’épaule"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Traumatisme de cheville en inversion forcée — Suspicion d'<span class=\"kw-etio\">entorse du ligament collatéral latéral</span> (faisceau <span class=\"kw-etio\">LTFA</span> ++) — l'<span class=\"kw-def\">urgence traumatique la plus fréquente</span>","detail":"<h4>CAT — Entorse de cheville (l<span class=\"kw-chiffre\">iga</span>ment collatéral latéral) — Du traumatisme en inversion au choix thérapeutique selon la gravité</h4>","branches":[{"to":"q-rx","label":"Évaluation aux urgences","color":"blue"}]},{"id":"q-rx","kind":"decision","label":"<span class=\"kw-imagerie\">Radiographie</span> (mortaise + profil) selon <span class=\"kw-clinique\">les</span> critères d'Ottawa — RX indiquée si <span class=\"kw-chiffre\">≥ 1</span> critère : <span class=\"kw-chiffre\">âge < 18 ou > 55 ans</span>, douleur osseuse des <span class=\"kw-clinique\">malléoles sur 6 cm</span>, de la <span class=\"kw-clinique\">base du 5e métatarsien</span> ou de l'<span class=\"kw-clinique\">os naviculaire</span>, ou <span class=\"kw-alerte\">impossibilité de faire 4 pas</span>","branches":[{"to":"t-ortho","label":"Fracture / lésion ostéochondrale du talus","color":"red"},{"to":"q-gravite","label":"Pas de fracture (ou RX non indiquée)","color":"green"}]},{"id":"t-ortho","kind":"terminal","label":"Traitement orthopédique — Entorse grave (stade 3, rupture) ou fracture associée","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Immobilisation par botte plâtrée ou en résine</span> pendant <span class=\"kw-chiffre\">6 semaines</span></li><li><span class=\"kw-ttt\">Sans appui</span> si <span class=\"kw-radio\">fracture ostéochondrale du talus</span>, <span class=\"kw-ttt\">avec appui</span> si entorse isolée</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Thromboprophylaxie</span> et sa <span class=\"kw-def\">surveillance</span></li><li><span class=\"kw-ttt\">Rééducation proprioceptive</span> ; reprise du sport à <span class=\"kw-chiffre\">12 semaines</span></li></ul>"},{"id":"q-gravite","kind":"decision","label":"<span class=\"kw-alerte\">Signes de gravité</span> clinique ? — <span class=\"kw-clinique\">Craquement audible</span>, <span class=\"kw-alerte\">appui impossible immédiat et persistant</span>, <span class=\"kw-radio\">hématome « oeuf de pigeon »</span>, <span class=\"kw-clinique\">tiroir talien antérieur</span> ou <span class=\"kw-clinique\">bâillement tibio-talien</span>","branches":[{"to":"t-ortho","label":"Oui = entorse grave (stade 3)","color":"red"},{"to":"q-stade","label":"Non","color":"green"}]},{"id":"q-stade","kind":"decision","label":"Examen au 4e-5e jour : préciser le <span class=\"kw-def\">stade</span> lésionnel — Examen le plus <span class=\"kw-def\">spécifique</span> du bilan l<span class=\"kw-chiffre\">iga</span>mentaire","branches":[{"to":"t-rice","label":"Stade 1 bénin (étirement, pas de déficit)","color":"green"},{"to":"t-fonctionnel","label":"Stade 2 moyen (distension, instabilité débutante)","color":"amber"}]},{"id":"t-rice","kind":"terminal","label":"Traitement symptomatique — protocole RICE — Entorse bénigne (stade 1)","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Repos</span>, <span class=\"kw-ttt\">glaçage</span> 4x/j, <span class=\"kw-ttt\">compression</span> élastique, <span class=\"kw-ttt\">élévation</span> pendant <span class=\"kw-chiffre\">3 jours</span></li><li>Reprise d'appui sous <span class=\"kw-ttt\">contention</span> pendant <span class=\"kw-chiffre\">7 jours</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Reprise du sport selon la douleur</li><li>Pas de séquelle sous <span class=\"kw-ttt\">rééducation proprioceptive</span> bien conduite</li></ul>"},{"id":"t-fonctionnel","kind":"terminal","label":"Traitement fonctionnel — Entorse de moyenne gravité (stade 2)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Strapping</span> ou <span class=\"kw-ttt\">orthèse stabilisatrice</span> portée ≥ <span class=\"kw-chiffre\">21 jours</span></li><li><span class=\"kw-ttt\">Rééducation proprioceptive</span> pendant <span class=\"kw-chiffre\">6 semaines</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Thromboprophylaxie</span> si appui impossible</li><li>Dépister l'<span class=\"kw-etio\">instabilité chronique</span> ; reprise du sport à <span class=\"kw-chiffre\">6 semaines</span> sous strapping</li></ul>"}]},"cards":[{"i":"7a82875d7c45","n":361,"o":"361-1","u":"Définition","t":"Connaître la définition d’une tendinopathie, d’une bursopathie, d’une enthésopathie","q":"Quelle est la définition d'une enthésopathie ?","a":"<p>Une enthésopathie est une pathologie des <strong>enthèses</strong>, qui sont les insertions <strong>tendino-capsulo-ligamentaires</strong> sur l'os. Elle peut être d'origine <strong>mécanique</strong> (liée par exemple à des activités sportives ou des gestes répétitifs) ou <strong>inflammatoire</strong> (comme dans les <strong>spondylarthropathies</strong>, notamment la spondylarthrite ankylosante, le rhumatisme psoriasique ou les MICI) et est alors appelée <strong>enthésite</strong>. Elle peut évoluer jusqu'à la formation d'un <strong>enthésophyte</strong>.</p>"},{"i":"bd376df646d1","n":361,"o":"361-1","u":"Définition","t":"Connaître la définition d’une tendinopathie, d’une bursopathie, d’une enthésopathie","q":"Quelle est la définition d'une bursopathie ?","a":"<p>Une bursopathie est une pathologie des <strong>bourses séreuses</strong>. Ces dernières sont des tissus de glissement situés entre la peau, les muscles, les tendons, les ligaments et les os, remplies de liquide synovial. Une bursopathie peut être d'origine <strong>mécanique</strong>, <strong>inflammatoire</strong> (microcristalline, rhumatismale) ou <strong>infectieuse</strong>. Un <strong>hygroma</strong> est une bursopathie superficielle, typiquement au coude ou au genou.</p>"},{"i":"f1af8a794334","n":361,"o":"361-1","u":"Définition","t":"Connaître la définition d’une tendinopathie, d’une bursopathie, d’une enthésopathie","q":"Quelle est la définition d'une tendinopathie ?","a":"<p>Une tendinopathie est une pathologie des <strong>tendons</strong>, structures fibreuses reliant le muscle à l'os. Elle peut être <strong>inflammatoire</strong> et/ou <strong>dégénérative</strong>. Il est à noter que le terme \"tendinite\" est souvent impropre car l'examen microscopique révèle principalement une dégénérescence, et non une inflammation, sauf si la gaine tendineuse est touchée.</p>"},{"i":"0637fc542c6a","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quel est le mécanisme lésionnel typique d'une rupture méniscale du genou ?","a":"<p>Le mécanisme lésionnel typique d'une rupture méniscale du genou est un <strong>mouvement de torsion</strong> en charge ou un <strong>relèvement d'une position accroupie</strong>.</p>"},{"i":"1d318480e26e","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Comment évalue-t-on cliniquement une lésion du ligament croisé antérieur (LCA) du genou ?","a":"<p>Une lésion du ligament croisé antérieur (LCA) du genou s'évalue cliniquement principalement par le <strong>test de Lachman</strong> (recherche d'un arrêt mou) et le <strong>test du ressaut rotatoire</strong> (Jerk test).</p>"},{"i":"201cbf097fb9","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quel est le mécanisme le plus fréquent des lésions ligamentaires du pivot central du genou ?","a":"<p>Le mécanisme le plus fréquent des lésions ligamentaires du pivot central du genou est un <strong>sport de pivot</strong> (ex: ski) ou <strong>pivot-contact</strong> (ex: football), impliquant une entorse avec une combinaison de <strong>valgus/varus</strong> et de <strong>rotation</strong>.</p>"},{"i":"47c76bcc1e49","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quels sont les signes cliniques orientant vers une lésion méniscale du genou ?","a":"<p>Les signes cliniques orientant vers une lésion méniscale du genou sont :</p><ul><li>Une <strong>douleur mécanique</strong>, souvent face interne / postéro-médiale.</li><li>Un <strong>épanchement à l'effort</strong>.</li><li>Un <strong>blocage méniscal</strong> (douleur brutale associée à un blocage de l'extension, la flexion restant possible).</li></ul>"},{"i":"660c3ee931ff","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quelle est la 'triade malheureuse de Trillat' et quelle est son implication principale ?","a":"<p>La 'triade malheureuse de Trillat' est une lésion combinant la rupture du <strong>LCA</strong>, la lésion du <strong>ménisque médial</strong> et l'atteinte du <strong>plan médial</strong>, survenant après un mécanisme en valgus + flexion + rotation externe. Sa principale implication est qu'une rupture du LCA <strong>augmente les contraintes</strong> sur la corne postérieure du ménisque médial, favorisant son usure, puis celle du cartilage, conduisant à une <strong>gonarthrose secondaire</strong>.</p>"},{"i":"76afe84c2cb5","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quels sont les tests cliniques spécifiques pour diagnostiquer une lésion méniscale du genou ?","a":"<p>Les tests cliniques spécifiques pour diagnostiquer une lésion méniscale du genou sont :</p><ul><li>La <strong>douleur à la palpation de l'interligne</strong> articulaire.</li><li>Le <strong>Grinding-test d'Apley</strong>.</li><li>Le <strong>test de Mac Murray</strong> (recherche d'un ressaut et d'une douleur).</li><li>Le <strong>signe de Genety</strong> (flessum asymétrique en décubitus ventral).</li></ul>"},{"i":"ffa7038ef339","n":361,"o":"361-10","u":"Diagnostic positif","t":"Savoir évoquer une lésion du pivot central du genou et/ou des lésions méniscales","q":"Quels sont les principaux symptômes orientant vers une lésion ligamentaire du pivot central du genou ?","a":"<p>Les symptômes orientant vers une lésion ligamentaire du pivot central du genou sont :</p><ul><li>Une <strong>laxité</strong> (mouvements anormaux) ± <strong>instabilité</strong> (sensation de lâchage / insécurité).</li><li>Un <strong>épanchement</strong>, spontané ou à l'effort.</li><li>Une <strong>douleur</strong>.</li></ul>"},{"i":"09fd2b6f7e55","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Que peut mettre en évidence l'échographie dans le cadre d'une tendinopathie ou rupture de la coiffe des rotateurs ?","a":"<p>L'échographie peut mettre en évidence :</p><ul><li><strong>Épaississement/désorganisation</strong> du tendon.</li><li><strong>Rupture transfixiante</strong> ou partielle.</li><li>Présence d'une <strong>bursite</strong>.</li><li>L'état du <strong>tendon du biceps</strong>.</li></ul>"},{"i":"1d34b412195b","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Quand les examens d'IRM ou d'arthroscanner sont-ils indiqués pour une tendinopathie de la coiffe des rotateurs ?","a":"<p>L'IRM ou l'arthroscanner sont des examens de <strong>seconde intention</strong>. Ils sont réservés à l'<strong>échec du traitement médical</strong>, chez un <strong>sujet jeune</strong>, lorsque une <strong>réparation chirurgicale est envisagée</strong>. Ces examens précisent le siège, l'étendue, la rétraction et la dégénérescence graisseuse des tendons.</p>"},{"i":"206f9b885bdd","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Quels signes indirects une radiographie peut-elle révéler dans les différents types de lésion de la coiffe des rotateurs ?","a":"<ul><li><strong>Tendinopathie simple :</strong> RX habituellement normale.</li><li><strong>Tendinopathie calcifiante :</strong> Présence de <strong>calcifications intra-tendineuses</strong>.</li><li><strong>Rupture de coiffe :</strong> <strong>Condensation/géodes du trochiter</strong>, <strong>enthésophyte acromial</strong>, <strong>pincement sous-acromial &lt; 7 mm</strong>, <strong>excentration céphalique</strong> (omarthrose excentrée).</li></ul>"},{"i":"36cd72fada25","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Quels sont les clichés radiographiques à réaliser et les objectifs de la radiographie dans le contexte d'une tendinopathie de la coiffe des rotateurs ?","a":"<p>Les clichés à réaliser sont :</p><ul><li>Face <strong>trois rotations</strong> (neutre, interne, externe)</li><li>Profil de Lamy (<strong>profil d'omoplate</strong>)</li></ul><p>Les objectifs sont d'éliminer une <strong>pathologie osseuse</strong> (tumeur) ou <strong>articulaire</strong> (omarthrose primitive) et de rechercher des <strong>signes indirects</strong> évocateurs de tendinopathie ou de rupture.</p>"},{"i":"3a2f25f4fa63","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Quel est l'examen d'imagerie de première intention systématique face à une suspicion de tendinopathie de la coiffe des rotateurs ?","a":"<p>L'examen d'imagerie de première intention systématique est la <strong>radiographie</strong> de l'épaule.</p>"},{"i":"5e672b8b846b","n":361,"o":"361-13","u":"Examens complémentaires","t":"Connaître l’indication, l’intérêt et l’objectif des examens d’imagerie en première intention dans le cadre d’une tendinopathie de la coiffe des rotateurs","q":"Dans quelles situations l'échographie est-elle indiquée en première intention pour une tendinopathie de la coiffe des rotateurs ?","a":"<p>L'échographie est indiquée en première intention en cas de <strong>doute de rupture</strong> ou de <strong>résistance au traitement</strong> médical initial. Il est important de noter qu'elle est insuffisante pour poser une indication opératoire.</p>"},{"i":"05fa5811f7f9","n":361,"o":"361-16","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant une lésion péri-articulaire et ligamentaire de la cheville","q":"Comment interpréter les clichés radiographiques spécifiques (incidence de Mortaise et cliché de profil) dans les lésions péri-articulaires et ligamentaires de la cheville ?","a":"<ul><li>L'<strong>incidence de Mortaise</strong> (face, rotation médiale 20°) permet de rechercher :<ul><li>Un <strong>bâillement articulaire</strong> ou un <strong>diastasis talo-malléolaire</strong> ou de la <strong>syndesmose</strong>.</li><li>Une <strong>fracture ostéochondrale du dôme du talus</strong> (nécessitant une TDM si suspectée).</li><li>Des <strong>arrachements ostéo-périostés</strong>.</li><li>Des <strong>fractures malléolaires peu déplacées</strong>.</li></ul></li><li>Le <strong>cliché de profil</strong> permet de rechercher :<ul><li>Une <strong>hémarthrose</strong> (refoulement de la ligne graisseuse), qui évoque une <strong>fracture ostéochondrale du talus</strong>.</li><li>Le contrôle du <strong>parallélisme de l'interligne</strong>.</li><li>Des lésions potentielles de la <strong>base du 5ème métatarsien</strong> et du <strong>naviculaire</strong>.</li></ul></li></ul>"},{"i":"2fbf63b14beb","n":361,"o":"361-16","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant une lésion péri-articulaire et ligamentaire de la cheville","q":"Quels sont l'intérêt et la place de l'échographie et de l'imagerie en coupes (TDM/IRM) dans l'exploration des lésions péri-articulaires et ligamentaires de la cheville ?","a":"<ul><li>L'<strong>échographie</strong> permet de :<ul><li>Affirmer une <strong>hémarthrose</strong>, qui est un <strong>signe de gravité</strong>.</li><li>Visualiser la <strong>rupture ligamentaire</strong> et en apprécier l'étendue.</li></ul></li><li>L'<strong>imagerie en coupes (TDM/IRM)</strong> a peu de place en urgence, mais est indiquée pour :<ul><li>Rechercher des <strong>fractures ostéochondrales du talus</strong> (notamment si hémarthrose).</li><li>Diagnostiquer une <strong>fracture du tubercule latéral du talus</strong>, qui peut être un piège diagnostique mimant une « entorse » par éversion.</li></ul></li><li>Les <strong>clichés dynamiques</strong> ne sont <strong>pas indiqués en urgence</strong>, mais sont utiles pour le bilan d'instabilité chronique (laxité en varus &gt; 10°, tiroir antérieur &gt; 8 mm).</li><li>Un piège classique est qu'une « entorse » de cheville chez un sujet de <strong>plus de 60 ans est rarissime</strong> et doit faire rechercher une <strong>fracture malléolaire</strong>, car l'os fragile se fracture avant que le ligament ne cède.</li></ul>"},{"i":"40b6b4b4fe20","n":361,"o":"361-16","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant une lésion péri-articulaire et ligamentaire de la cheville","q":"Dans le cadre d'une entorse isolée de la cheville, quel est l'intérêt et l'indication des radiographies standard ?","a":"<p>En cas d'entorse isolée de la cheville, les radiographies sont <strong>normales</strong> car il s'agit d'une lésion ligamentaire sans perte des rapports articulaires. Leur rôle est uniquement de rechercher des <strong>lésions associées</strong> ou un <strong>diagnostic différentiel</strong>, notamment une <strong>fracture</strong>.</p><p>L'indication des radiographies est basée sur les <strong>critères d'Ottawa</strong> :</p><ul><li>Âge &lt; 18 ans ou &gt; 55 ans</li><li>Douleur à la palpation du bord postérieur des malléoles (sur 6 cm)</li><li>Douleur à la base du <strong>5ème métatarsien</strong> ou de l'<strong>os naviculaire</strong></li><li>Impossibilité de faire <strong>4 pas en plein appui</strong></li></ul>"},{"i":"0a8266b8114e","n":361,"o":"361-4","u":"Identifier une urgence","t":"Connaître l’urgence d’une bursite","q":"Quelle est l'unique urgence à connaître concernant les bursites, selon l'objectif de l'EDN ?","a":"<p>L'unique urgence à connaître est la <strong>bursite septique</strong>.</p>"},{"i":"6581399bdd69","n":361,"o":"361-4","u":"Identifier une urgence","t":"Connaître l’urgence d’une bursite","q":"Comment doit être investiguée une bursite pour confirmer son caractère septique et quel est l'agent pathogène le plus fréquent ?","a":"<p>Le diagnostic de bursite septique est confirmé par la <strong>ponction de la bourse</strong>. Une bursite septique est très évocatrice si les <strong>leucocytes sont &gt; 10⁶/mL</strong> (Se 95%, Sp 80%). Le germe principal est le <strong><em>Staphylococcus aureus</em></strong> (80% des cas).</p>"},{"i":"6d7a27092a80","n":361,"o":"361-4","u":"Identifier une urgence","t":"Connaître l’urgence d’une bursite","q":"Quels sont les éléments cliniques évocateurs d'une bursite septique superficielle ?","a":"<p>La bursite septique superficielle se manifeste par :</p><ul><li>Des <strong>signes inflammatoires locaux</strong> : tuméfaction de la bourse, érythème, chaleur</li><li>Une <strong>douleur</strong>, une gêne fonctionnelle</li><li>Une <strong>adénopathie</strong> satellite est possible</li><li>La <strong>fièvre est inconstante</strong> (20-75% des cas), rendant la présentation non spécifique d'emblée.</li></ul>"},{"i":"9efad738b3b0","n":361,"o":"361-4","u":"Identifier une urgence","t":"Connaître l’urgence d’une bursite","q":"Quelle est la prise en charge initiale d'une bursite septique confirmée ou fortement suspectée ?","a":"<p>La prise en charge initiale d'une bursite septique repose sur une <strong>antibiothérapie probabiliste</strong>, débutée après les prélèvements. Les molécules usuelles sont l'<strong>Augmentin / C1G</strong> ou la <strong>Clindamycine</strong> en cas d'allergie. Une <strong>chirurgie</strong> peut être envisagée en cas de forme réfractaire ou récidivante.</p>"},{"i":"00be8b993ed0","n":361,"o":"361-5","u":"Diagnostic positif","t":"Connaître les signes cliniques diagnostiques d’une tendinopathie","q":"Quels sont les examens d'imagerie recommandés pour une tendinopathie, selon la hiérarchie des intentions ?","a":"<p>La démarche d'imagerie est la suivante :</p><ul><li>En <strong>1<sup>re</sup> intention</strong> : <strong>Radiographie</strong> de l’articulation douloureuse pour rechercher un facteur favorisant, une calcification tendineuse ou un diagnostic différentiel.</li><li>En <strong>2<sup>e</sup> intention</strong> : <strong>Échographie</strong> et <strong>IRM</strong> (gold standard) en cas de doute diagnostique ou de résistance au traitement.</li></ul>"},{"i":"1ee92416b39f","n":361,"o":"361-5","u":"Diagnostic positif","t":"Connaître les signes cliniques diagnostiques d’une tendinopathie","q":"Quel est le signe négatif clé permettant de différencier une tendinopathie d'une atteinte articulaire ?","a":"<p>Le signe négatif clé est l'<strong>indolence lors de la mobilisation passive douce de l'articulation</strong>. Ceci permet de séparer la tendinopathie d'une atteinte directement articulaire.</p>"},{"i":"e88165ac0b78","n":361,"o":"361-5","u":"Diagnostic positif","t":"Connaître les signes cliniques diagnostiques d’une tendinopathie","q":"Selon l'objectif d'EDN, quels sont les différents stades de gravité d'une tendinopathie en fonction de la douleur à l'effort ?","a":"<p>La gravité de la tendinopathie peut être stadifiée selon l'impact de la douleur sur l'effort :</p><ul><li><strong>Stade 1</strong> : douleur après l’effort.</li><li><strong>Stade 2</strong> : douleur pendant l’effort, sans l’arrêter.</li><li><strong>Stade 3</strong> : douleur qui impose d’arrêter l’effort.</li></ul>"},{"i":"fd0c1703f055","n":361,"o":"361-5","u":"Diagnostic positif","t":"Connaître les signes cliniques diagnostiques d’une tendinopathie","q":"Comment établit-on le diagnostic clinique d'une tendinopathie ?","a":"<p>Le diagnostic de tendinopathie est clinique et repose sur la présence d'une <strong>triade sémiologique</strong> lors du testing musculo-tendineux :</p><ul><li><strong>Douleur à la palpation</strong> de l’insertion ou du corps tendineux.</li><li><strong>Douleur à la contraction contrariée</strong> (contre résistance) du muscle.</li><li><strong>Douleur à l’étirement passif</strong> du tendon.</li></ul>"},{"i":"02d9eebd6d7b","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Comment distinguer cliniquement une disjonction acromio-claviculaire de grade 2 et de grade 3 selon la classification de Rockwood ?","a":"<p>Le grade 2 implique une rupture des ligaments acromio-claviculaires avec une mobilité en touche de piano modérée et pas de tiroir antéro-postérieur. Le grade 3, en plus des lésions du grade 2, présente une <strong>rupture des ligaments coraco-claviculaires</strong> (trapézoïde et conoïde), ce qui se traduit par une <strong>touche de piano franche</strong> et un <strong>tiroir antéro-postérieur</strong>.</p>"},{"i":"048af0405e82","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quelles sont les complications nerveuses à rechercher après une luxation gléno-humérale, et quelle est la plus fréquente ?","a":"<p>La complication nerveuse la plus fréquente est l'atteinte du <strong>nerf axillaire</strong> (à vérifier par la sensibilité du moignon de l'épaule), surtout chez les patients de plus de 40 ans. D'autres nerfs peuvent être atteints comme le nerf radial ou le plexus brachial (en cas de luxation intra-coracoïdienne).</p>"},{"i":"3141b20b5804","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quels examens d'imagerie sont recommandés pour diagnostiquer une disjonction acromio-claviculaire, notamment en cas de doute sur la sévérité ?","a":"<p>Les examens d'imagerie comprennent une <strong>radiographie de face centrée sur l'articulation acromio-claviculaire</strong>, un <strong>profil de Lamy</strong> et un <strong>profil axillaire</strong>. En cas de doute, des <strong>clichés comparatifs en charge</strong> peuvent être réalisés.</p>"},{"i":"326d38ae39f7","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quel est le mécanisme lésionnel typique d'une luxation gléno-humérale antérieure (antéro-interne) ?","a":"<p>Le mécanisme est généralement <strong>indirect</strong>, faisant suite à une chute sur la main ou le coude avec le bras en <strong>abduction, rotation externe et rétropulsion</strong>, souvent chez des sujets jeunes, sportifs ou hyperlaxes.</p>"},{"i":"81de2d3e90d3","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quels sont les signes cliniques diagnostiques d'une luxation gléno-humérale antérieure à l'inspection ?","a":"<ul><li>Le <strong>signe de l'épaulette</strong> (saillie de l'acromion).</li><li>Le <strong>coup de hache externe</strong>.</li><li>La <strong>vacuité de l'espace sous-acromial</strong>.</li><li>La <strong>saillie de la tête humérale</strong> dans le sillon delto-pectoral.</li><li>Une <strong>attitude vicieuse irréductible en abduction-rotation externe</strong> (signe de Berger).</li></ul>"},{"i":"9ad486299e7c","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quels sont les signes cliniques d'une disjonction acromio-claviculaire, en particulier le signe de la touche de piano ?","a":"<p>Les signes cliniques incluent une <strong>douleur élective à la palpation de l'extrémité distale de la clavicule</strong>, une <strong>mobilité en touche de piano</strong> (verticale, qui correspond à la réductibilité de la luxation claviculaire sous la pression manuelle) et un <strong>tiroir antéro-postérieur</strong> (surtout aux stades 3 et 4 de Rockwood).</p>"},{"i":"beb0b7880030","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quels examens d'imagerie doivent être réalisés systématiquement avant toute réduction d'une luxation gléno-humérale ?","a":"<p>Il faut réaliser des <strong>radiographies de face</strong> et un <strong>profil de Lamy</strong> (profil d'omoplate), éventuellement complétés par une incidence de Garth. Ces examens montreront la tête humérale en avant de la glène et une rupture du cintre scapulo-huméral.</p>"},{"i":"fe41798e7cdc","n":361,"o":"361-6","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une luxation de l’articulation gléno-humérale et acromio-claviculaire et leurs complications","q":"Quelles sont les complications osseuses et tendineuses à rechercher après une luxation gléno-humérale ?","a":"<ul><li><strong>Complications osseuses</strong> : l'encoche de Malgaigne / Hill-Sachs (sur la tête humérale), la fracture du tubercule majeur (trochiter) et l'éculement de la glène (lésion de Bankart osseux).</li><li><strong>Complications tendineuses</strong> : la rupture de la coiffe des rotateurs (notamment le supra-épineux), à évoquer systématiquement chez les patients de plus de 45 ans.</li></ul>"},{"i":"069ab2758fec","n":361,"o":"361-7","u":"Identifier une urgence","t":"Connaître l’urgence d’une tendinopathie de la coiffe des rotateurs","q":"Quelle est la prise en charge initiale des urgences/hyperalgies de la coiffe des rotateurs (hors infection) ?","a":"<p>La prise en charge initiale repose sur les <strong>antalgiques</strong> et les <strong>anti-inflammatoires</strong>. Dans certains cas spécifiques de tendinite calcifiante, une <strong>ponction-lavage-aspiration de la calcification</strong> peut être envisagée.</p>"},{"i":"41131c0dc059","n":361,"o":"361-7","u":"Identifier une urgence","t":"Connaître l’urgence d’une tendinopathie de la coiffe des rotateurs","q":"Quel est le piège diagnostique majeur devant une épaule aiguë très douloureuse ?","a":"<p>Le piège est de ne pas confondre une épaule aiguë hyperalgique (comme la résorption de calcification) avec une <strong>arthrite septique</strong>. Devant une épaule aiguë très douloureuse, il faut <strong>éliminer systématiquement l'arthrite septique</strong> (urgence). Les signes d'alerte sont la <strong>fièvre</strong> et la <strong>rougeur</strong>, imposant une <strong>ponction articulaire</strong>.</p>"},{"i":"86b94199e92a","n":361,"o":"361-7","u":"Identifier une urgence","t":"Connaître l’urgence d’une tendinopathie de la coiffe des rotateurs","q":"Quelle est l'urgences de la tendinopathie de la coiffe des rotateurs liée à une résorption de calcification ?","a":"<p>L'urgence est l'<strong>épaule aiguë hyperalgique</strong> par résorption de calcification (rhumatisme à hydroxyapatite). Elle se manifeste par une douleur <strong>brutale</strong>, <strong>intense</strong>, <strong>diurne et nocturne</strong>, chez un patient présentant une tendinopathie calcifiante connue.</p>"},{"i":"d40994844aa2","n":361,"o":"361-7","u":"Identifier une urgence","t":"Connaître l’urgence d’une tendinopathie de la coiffe des rotateurs","q":"Quelle est la deuxième urgence de la tendinopathie de la coiffe des rotateurs, autre que la résorption de calcification ?","a":"<p>Il s'agit de la <strong>rupture massive aiguë de la coiffe</strong>, donnant un tableau « pseudo-paralytique ». Elle se caractérise par une <strong>impotence fonctionnelle sévère</strong> avec des <strong>mobilités passives conservées</strong>. Elle survient souvent après un <strong>traumatisme</strong> chez le sujet de <strong>plus de 45 ans</strong>.</p>"}]};